# numeric checks
assert math.isclose(math.hypot(6, 3, 2), 7) and 2 + 6 + 12 == 20
assert abs(1 * (1 - 0) - 1 * (0 - 1) + 0) == 2 and abs(2 - 1 + 2 - 6) / 3 == 1
assert 2 * 3 * 2 * 1 + 3 ** 2 * 2 == 30
assert math.isclose((8 - 2 + 12) / 3, 6) and math.isclose(math.sqrt(56), 2 * math.sqrt(14))
assert math.isclose(5 + 0.6 * 0.03 + 0.8 * -0.04, 4.986) and round(math.hypot(3.03, 3.96), 5) == 4.98623
assert math.isclose(2 * math.pi * (1 - math.cos(math.pi / 3)) * 8 / 3, 8 * math.pi / 3)
assert math.isclose(2 * math.pi * (8 - 4), 8 * math.pi) and math.isclose(2 * math.pi * 26 / 12, 13 * math.pi / 3)
assert math.isclose(1 / 3 + 1 / 2, 5 / 6) and math.isclose(3 * 4 * 2 * math.pi, 24 * math.pi)
assert math.isclose(3 * 0.25 * 2 * math.pi, 1.5 * math.pi) and math.isclose(3 / 5 * 4 * math.pi, 12 * math.pi / 5)
assert math.isclose(4 * math.pi / 3 + 2 * math.pi, 10 * math.pi / 3) and math.isclose((2 / 3) / (math.pi / 2), 4 / (3 * math.pi))
assert math.isclose(1 / 3 + 1 / 4, 7 / 12) and math.isclose(math.pi * 0.01 * 2, 0.02 * math.pi)
assert round(2 * math.pi * math.sqrt((6.371e6) ** 3 / 3.986e14)) == 5061

